{"content":""""Compare LASSO and Ridge regression with CV-based and AIC-based selection.

Reads gene expression features/response CSVs, validates inputs robustly,
trains 4 models (LASSO-CV, LASSO-AIC, Ridge-CV, Ridge-AIC), writes validation
predictions and a model comparison table.

Exit codes: 0 on success, 1 on any file/validation/processing error.
On failure no output files are written.
"""
import os
import sys

import numpy as np
import pandas as pd
from sklearn.linear_model import LassoCV, LassoLarsIC, Ridge, RidgeCV
from sklearn.metrics import mean_absolute_error, mean_squared_error, r2_score

TRAIN_FEATURES = "/app/train_features.csv"
TRAIN_RESPONSE = "/app/train_response.csv"
VAL_FEATURES = "/app/val_features.csv"
PREDICTIONS_OUT = "/app/predictions.txt"
COMPARISON_OUT = "/app/model_comparison.csv"


def fail(msg):
    print(f"Error: {msg}", file=sys.stderr)
    # Ensure no output files remain on failure.
    for p in (PREDICTIONS_OUT, COMPARISON_OUT):
        try:
            if os.path.exists(p):
                os.remove(p)
        except OSError:
            pass
    sys.exit(1)


def check_file(path):
    if not os.path.exists(path):
        fail(f"required input file missing: {path}")
    if not os.path.isfile(path):
        fail(f"required input is not a file: {path}")
    if os.path.getsize(path) == 0:
        fail(f"required input file is empty: {path}")
    with open(path, "r") as f:
        content = f.read()
    if not content.strip():
        fail(f"required input file is empty: {path}")
    lines = [ln for ln in content.strip().splitlines() if ln.strip()]
    if len(lines) < 2:
        fail(f"required input file has no data rows: {path}")


def _is_numeric_row(row):
    try:
        for v in row:
            if v is None:
                return False
            s = str(v).strip()
            if s == "" or s.lower() == "nan":
                # empty/missing -> not plain numeric, handled later as missing
                return False
            float(s)
        return True
    except (ValueError, TypeError):
        return False


def load_numeric_csv(path, name, expect_single_col=False):
    """Load CSV as numeric numpy array, tolerating an optional header row."""
    try:
        df_raw = pd.read_csv(path, header=None, dtype=str, keep_default_na=True)
    except Exception as e:
        fail(f"invalid data in {path}: cannot parse CSV ({e})")
    if df_raw.shape[0] == 0 or df_raw.shape[1] == 0:
        fail(f"invalid data in {path}: no data found")
    # Strip whitespace from cells
    df_raw = df_raw.apply(lambda col: col.str.strip() if col.dtype == object else col)

    first_row = df_raw.iloc[0].tolist()
    if _is_numeric_row(first_row):
        data_str = df_raw
    else:
        # First row is a header; require at least one data row after it
        if df_raw.shape[0] < 2:
            fail(f"invalid data in {path}: no data rows (only header)")
        data_str = df_raw.iloc[1:].reset_index(drop=True)

    n_rows, n_cols = data_str.shape
    if n_rows == 0:
        fail(f"invalid data in {path}: no data rows")
    if expect_single_col and n_cols != 1:
        fail(
            f"invalid data in {path}: expected single response column, "
            f"found {n_cols} columns"
        )
    if not expect_single_col and n_cols < 1:
        fail(f"invalid data in {path}: no feature columns found")

    # Convert to numeric, detecting non-numeric values
    try:
        data = data_str.apply(pd.to_numeric, errors="raise").to_numpy(dtype=float)
    except Exception:
        fail(f"invalid data in {path}: contains non-numeric values")
        raise  # unreachable

    # Missing values check (empty fields become NaN via read_csv)
    if np.isnan(data).any():
        fail(f"invalid data in {path}: contains missing values")
    if np.isinf(data).any():
        fail(f"invalid data in {path}: contains infinite values")
    return data


def main():
    # 1. File existence / non-emptiness
    for p in (TRAIN_FEATURES, TRAIN_RESPONSE, VAL_FEATURES):
        check_file(p)

    # 2. Load + format validation
    X_train = load_numeric_csv(TRAIN_FEATURES, "train_features")
    y = load_numeric_csv(TRAIN_RESPONSE, "train_response", expect_single_col=True).ravel()
    X_val = load_numeric_csv(VAL_FEATURES, "val_features")

    n_samples, n_features = X_train.shape

    # 3. Dimension consistency
    if y.shape[0] != n_samples:
        fail(
            f"dimension mismatch: train_features has {n_samples} rows but "
            f"train_response has {y.shape[0]} rows"
        )
    if X_val.shape[1] != n_features:
        fail(
            f"dimension mismatch: train_features has {n_features} columns but "
            f"val_features has {X_val.shape[1]} columns"
        )
    if X_val.shape[0] == 0:
        fail("invalid data in val_features.csv: no data rows")

    # 4. Data quality / processability checks
    if n_samples < 5:
        fail(f"insufficient samples: only {n_samples} training rows (minimum 5)")
    if n_features < 1:
        fail("insufficient features: no feature columns found")
    if np.all(X_train == 0):
        fail("data cannot be processed: all training features are zero")
    col_var = np.var(X_train, axis=0)
    if np.all(col_var == 0):
        fail("data cannot be processed: all training features are constant")
    if np.var(y) == 0:
        fail("data cannot be processed: response values are constant")
    # Warn (not fatal) about individual constant features
    n_const = int(np.sum(col_var == 0))
    if n_const > 0:
        print(
            f"Warning: {n_const} constant feature column(s) detected.",
            file=sys.stderr,
        )

    cv = min(5, n_samples)
    if cv < 2:
        fail("insufficient samples for cross-validation")

    # 5. Train models
    models = {}
    try:
        lasso_cv = LassoCV(cv=cv, random_state=0, max_iter=10000)
        lasso_cv.fit(X_train, y)
        models[("LASSO", "CV")] = lasso_cv

        lasso_aic = LassoLarsIC(criterion="aic", max_iter=500)
        lasso_aic.fit(X_train, y)
        models[("LASSO", "AIC")] = lasso_aic
    except Exception as e:
        fail(f"data cannot be processed: LASSO training failed ({e})")

    try:
        ridge_cv = RidgeCV(alphas=np.logspace(-3, 5, 50), cv=cv)
        ridge_cv.fit(X_train, y)
        models[("Ridge", "CV")] = ridge_cv
    except Exception as e:
        fail(f"data cannot be processed: Ridge CV training failed ({e})")

    # Ridge with AIC-based alpha selection (manual grid search).
    try:
        alphas = np.logspace(-3, 5, 50)
        best_aic = np.inf
        best_alpha = alphas[0]
        best_ridge = None
        for a in alphas:
            r = Ridge(alpha=a)
            r.fit(X_train, y)
            resid = y - r.predict(X_train)
            rss = float(np.sum(resid ** 2))
            if rss <= 0 or not np.isfinite(rss):
                continue
            k = n_features + 1  # coefficients + intercept
            aic = n_samples * np.log(rss / n_samples) + 2 * k
            if aic < best_aic:
                best_aic = aic
                best_alpha = a
                best_ridge = r
        if best_ridge is None:
            fail("data cannot be processed: Ridge AIC selection failed (singular matrix or invalid RSS)")
        models[("Ridge", "AIC")] = best_ridge
    except SystemExit:
        raise
    except Exception as e:
        fail(f"data cannot be processed: Ridge AIC training failed ({e})")

    # 6. Evaluate on training data + predict validation
    rows = []
    val_preds = {}
    try:
        for (mtype, crit), model in models.items():
            train_pred = model.predict(X_train)
            if not np.all(np.isfinite(train_pred)):
                fail(f"data cannot be processed: {mtype}-{crit} produced non-finite training predictions")
            r2 = float(r2_score(y, train_pred))
            mse = float(mean_squared_error(y, train_pred))
            mae = float(mean_absolute_error(y, train_pred))
            alpha = float(getattr(model, "alpha_", getattr(model, "alpha", np.nan)))
            rows.append(
                {
                    "model": mtype,
                    "selection": crit,
                    "criterion": crit,
                    "alpha": alpha,
                    "R2": r2,
                    "MSE": mse,
                    "MAE": mae,
                }
            )
            vp = model.predict(X_val)
            if not np.all(np.isfinite(vp)):
                fail(f"data cannot be processed: {mtype}-{crit} produced non-finite validation predictions")
            val_preds[(mtype, crit)] = vp
    except SystemExit:
        raise
    except Exception as e:
        fail(f"data cannot be processed: evaluation failed ({e})")

    # Choose best model by R2 (tie-break by MSE) for predictions.txt,
    # which holds one prediction per validation row.
    order = sorted(rows, key=lambda r: (-r["R2"], r["MSE"]))
    best = order[0]
    best_key = (best["model"], best["selection"])
    best_pred = val_preds[best_key]
    print(
        f"Best model: {best_key[0]}-{best_key[1]} "
        f"(R2={best['R2']:.4f}, MSE={best['MSE']:.4f})"
    )

    # 7. Write outputs (only after everything succeeded)
    try:
        with open(PREDICTIONS_OUT, "w") as f:
            for v in best_pred:
                f.write(f"{float(v):.6f}\n")
        comp = pd.DataFrame(rows, columns=["model", "selection", "criterion", "alpha", "R2", "MSE", "MAE"])
        # Required columns: model type, selection criterion, R2, MSE, MAE.
        comp.to_csv(COMPARISON_OUT, index=False)
    except Exception as e:
        fail(f"failed to write output files ({e})")

    print(f"Wrote {len(best_pred)} predictions to {PREDICTIONS_OUT}")
    print(f"Wrote model comparison to {COMPARISON_OUT}")


if __name__ == "__main__":
    main()
